<?php
require_once dirname(__DIR__).'/config/database.php';$id=(int)($_GET['id']??0);if(!$id){http_response_code(400);exit;}$pdo=db();$s=$pdo->prepare('SELECT mime_type,base64_data,source_type,local_path FROM couple_images WHERE id=:id');$s->execute([':id'=>$id]);$img=$s->fetch();if(!$img){http_response_code(404);exit;}if($img['source_type']==='local'){ $p=(string)$img['local_path']; if(!preg_match('~^images/[A-Za-z0-9._-]+$~',$p)){http_response_code(403);exit;} header('Location:/'.$p,true,302);exit;} $bin=base64_decode((string)$img['base64_data'],true);if($bin===false){http_response_code(500);exit;}header('Content-Type:'.($img['mime_type']?:'application/octet-stream'));header('Content-Length:'.strlen($bin));header('Cache-Control:public,max-age=3600');header('X-Content-Type-Options:nosniff');echo $bin;
